using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using DsBridge.Haptics;

namespace DsBridge;

/// <summary>Test checklist ("quests" for testing new haptics). The plan (haptics/tests/active.json, generated by
/// tools/haptic_intel.py testplan or written by hand) lists tasks; a task is done when what it names really happened:
///   "rule:&lt;id or glob&gt;"              - the effect of that rule played (not dropped by cooldown / situation / rejection)
///   "event:&lt;type&gt;:&lt;phase&gt;[k=v,...]" - the game sent that event
/// The list is written for the mod (Mods/G1R_DualSenseBridge/DsB_TestHud.txt, drawn by DsB_TestHud.as in the top right corner):
///   done task  -> green, mark + "(n)" = how many times it was repeated after the first; the SHARE button shows / hides the list.
/// At the end (and every change) the counts are saved to reports/tests/&lt;journal&gt;.json, so the agent sees what was reproduced.</summary>
public sealed class TestHud
{
    sealed class Task { public string Id = "", Text = ""; public List<string> On = new(); public int Count; public DateTime? First; }
    readonly List<Task> _tasks = new();
    readonly string _hudPath, _reportPath, _title, _done, _todo;
    readonly Action<string> _log;
    volatile bool _show = true; bool _dirty = true; DateTime _lastWrite = DateTime.MinValue;
    readonly object _lk = new();
    public bool Active => _tasks.Count > 0;
    public int Total => _tasks.Count;
    public int Done { get { lock (_lk) return _tasks.Count(t => t.Count > 0); } }

    TestHud(string hudPath, string reportPath, string title, string done, string todo, Action<string> log)
    { _hudPath = hudPath; _reportPath = reportPath; _title = title; _done = done; _todo = todo; _log = log; }

    /// <summary>Loads a plan (null / missing / "enabled": false -> an inactive HUD that only hides the list in the game).</summary>
    public static TestHud Load(string? planPath, string modDir, string reportPath, Action<string> log)
    {
        string hud = Path.Combine(modDir, "DsB_TestHud.txt");
        if (planPath == null || !File.Exists(planPath)) return new TestHud(hud, reportPath, "", "", "", log);
        using var d = JsonDocument.Parse(File.ReadAllText(planPath), new JsonDocumentOptions { CommentHandling = JsonCommentHandling.Skip, AllowTrailingCommas = true });
        var r = d.RootElement;
        string S(string k, string def) => r.TryGetProperty(k, out var x) && x.ValueKind == JsonValueKind.String ? x.GetString()! : def;
        var h = new TestHud(hud, reportPath, S("title", "Тест"), S("doneMark", "✓"), S("todoMark", "○"), log);
        if (r.TryGetProperty("enabled", out var en) && en.ValueKind == JsonValueKind.False) return h;
        foreach (var t in r.GetProperty("tasks").EnumerateArray())
        {
            var task = new Task { Id = t.TryGetProperty("id", out var id) ? id.GetString()! : "", Text = t.GetProperty("text").GetString()! };
            foreach (var o in t.GetProperty("on").EnumerateArray()) task.On.Add(o.GetString()!);
            h._tasks.Add(task);
        }
        log($"test HUD: {h._tasks.Count} task(s) from {planPath} (SHARE on the pad shows / hides the list in the game)");
        return h;
    }

    static readonly HashSet<string> NotPlayed = new(StringComparer.OrdinalIgnoreCase) { "skip", "cooldown", "situation", "rejected", "group-rejected", "error", "stop", "stop-all" };

    static bool Glob(string pattern, string value) =>
        Regex.IsMatch(value, "^" + Regex.Escape(pattern).Replace("\\*", ".*").Replace("\\?", ".") + "$", RegexOptions.IgnoreCase);

    static bool EventMatch(string sig, GameEvent ev)
    {
        var m = Regex.Match(sig, @"^([a-z_0-9]+):([a-z*]+)(?:\[(.*)\])?$");
        if (!m.Success || m.Groups[1].Value != ev.Type || (m.Groups[2].Value != "*" && m.Groups[2].Value != ev.Phase)) return false;
        if (m.Groups[3].Success)
            foreach (var kv in m.Groups[3].Value.Split(',', StringSplitOptions.RemoveEmptyEntries))
            {
                var p = kv.Split('=', 2);
                if (p.Length == 2 && !Glob(p[1], ev.Get(p[0]) ?? "")) return false;
            }
        return true;
    }

    /// <summary>Called for every game event with the decisions the haptic runtime took for it.</summary>
    public void Observe(GameEvent ev, IEnumerable<Decision> decisions, DateTime now)
    {
        if (!Active) return;
        var played = decisions.Where(d => !NotPlayed.Contains(d.Route)).Select(d => d.RuleId).ToList();
        lock (_lk)
            foreach (var t in _tasks)
            {
                bool hit = t.On.Any(o => o.StartsWith("rule:") ? played.Any(r => Glob(o[5..], r)) : o.StartsWith("event:") && EventMatch(o[6..], ev));
                if (!hit) continue;
                t.Count++; t.First ??= now; _dirty = true;
                _log($"test: {(t.Count == 1 ? "DONE" : $"again ({t.Count - 1})")} - {t.Text}");
            }
    }

    /// <summary>SHARE pressed (input thread).</summary>
    public void Toggle() { _show = !_show; _dirty = true; }

    /// <summary>Writes the list for the mod when it changed (at most every 150 ms) and the session report.</summary>
    public void Flush(DateTime now, bool force = false)
    {
        if (!force && (!_dirty || (now - _lastWrite).TotalMilliseconds < 150)) return;
        _dirty = false; _lastWrite = now;
        var sb = new StringBuilder();
        lock (_lk)
        {
            sb.Append("show=").Append(_show && Active ? 1 : 0).Append('\n');
            if (Active)
            {
                sb.Append("title=").Append(_title).Append($"  {_tasks.Count(t => t.Count > 0)}/{_tasks.Count}").Append('\n');
                foreach (var t in _tasks)
                    sb.Append("task=").Append(t.Count > 0 ? "1|" : "0|")
                      .Append(t.Count > 0 ? _done + " " + (t.Count > 1 ? $"({t.Count - 1}) " : "") : _todo + " ").Append(t.Text).Append('\n');
            }
        }
        try
        {
            if (Directory.Exists(Path.GetDirectoryName(_hudPath)))
            {
                var tmp = _hudPath + ".tmp";
                File.WriteAllText(tmp, sb.ToString(), new UTF8Encoding(true));   // BOM: the game reads it as UTF-8 for sure
                File.Move(tmp, _hudPath, true);
            }
        }
        catch (Exception ex) { _log("test HUD write: " + ex.Message); }
        if (!Active) return;
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(_reportPath)!);
            lock (_lk)
                File.WriteAllText(_reportPath, JsonSerializer.Serialize(new
                {
                    title = _title, updated = now.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"), done = _tasks.Count(t => t.Count > 0), total = _tasks.Count,
                    tasks = _tasks.Select(t => new { t.Id, t.Text, times = t.Count, first = t.First?.ToLocalTime().ToString("HH:mm:ss"), t.On })
                }, new JsonSerializerOptions { WriteIndented = true, Encoder = System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping }));
        }
        catch (Exception ex) { _log("test report: " + ex.Message); }
    }

    /// <summary>On exit: hide the list in the game, keep the report.</summary>
    public void Close(DateTime now)
    {
        _show = false; _dirty = true; Flush(now, true);
        if (Active) _log($"test: {Done}/{Total} task(s) done -> {_reportPath}");
    }
}
